package com.oratoriamaster.ia;
import android.app.*;import android.os.*;import android.graphics.Color;import android.speech.RecognizerIntent;import android.content.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 String[] names={"Dicción","Muletillas","Respiración y pausas","Persuasión","Improvisación","Debate","Narración","Presentación","Oratoria jurídica","Preguntas difíciles","Entonación","Confianza escénica"};
 String[] tasks={"Pronuncia un trabalenguas lentamente y con claridad.","Habla un minuto sin utilizar muletillas.","Practica pausas naturales mientras explicas una idea.","Defiende la importancia de la lectura.","Improvisa un discurso sobre un objeto cotidiano.","Expón una tesis y dos argumentos.","Cuenta una historia con inicio, desarrollo y final.","Preséntate ante un público imaginario.","Formula un alegato sobre un caso ficticio.","Responde con calma a una pregunta inesperada.","Alterna el ritmo y la entonación al leer.","Presenta un discurso breve con seguridad."};
 LinearLayout root; TextView timer; int seconds=0,selected=0;boolean running=false;Handler handler=new Handler(Looper.getMainLooper());final int REQ=12;
 void page(String title){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(32,36,32,32);root.setBackgroundColor(Color.rgb(240,247,255));scroll.addView(root);setContentView(scroll);TextView heading=new TextView(this);heading.setText(title);heading.setTextColor(Color.rgb(24,60,120));heading.setTextSize(25);root.addView(heading);}
 void text(String value){TextView v=new TextView(this);v.setText(value);v.setTextSize(17);v.setPadding(4,20,4,20);root.addView(v);}
 void button(String title,Runnable run){Button b=new Button(this);b.setAllCaps(false);b.setText(title);root.addView(b);b.setOnClickListener(v->run.run());}
 public void onCreate(Bundle b){super.onCreate(b);home();}
 void home(){running=false;page("ORATORIA MASTER IA");text("Entrenamiento de oratoria sin conexión. 12 habilidades disponibles.");text("Prácticas completadas: "+getPreferences(0).getInt("count",0));button("Comenzar",()->menu());}
 void menu(){page("Elige tu habilidad");for(int i=0;i<names.length;i++){final int n=i;button((i+1)+". "+names[i],()->{selected=n;practice();});}button("Inicio",()->home());}
 void practice(){running=false;seconds=0;page(names[selected]);text(tasks[selected]);timer=new TextView(this);timer.setTextSize(32);timer.setText("00:00");root.addView(timer);button("Iniciar / pausar",()->{running=!running;if(running)tick();});button("Reiniciar",()->{running=false;seconds=0;timer.setText("00:00");});button("Dictar y analizar discurso",()->speech());button("Completar práctica",()->{getPreferences(0).edit().putInt("count",getPreferences(0).getInt("count",0)+1).apply();home();});button("Volver",()->menu());}
 void tick(){handler.postDelayed(()->{if(running){seconds++;timer.setText(String.format(Locale.US,"%02d:%02d",seconds/60,seconds%60));tick();}},1000);}
 void speech(){try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"es-EC");startActivityForResult(i,REQ);}catch(Exception e){text("Reconocimiento de voz no disponible en este teléfono.");}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==REQ&&result==RESULT_OK&&data!=null){ArrayList<String> list=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(list!=null&&!list.isEmpty()){String speech=list.get(0);String[] words=speech.trim().split("\\s+");int fillers=0;for(String w:words)if(w.equalsIgnoreCase("eh")||w.equalsIgnoreCase("este"))fillers++;page("Evaluación básica");text("Transcripción: "+speech);text("Palabras: "+words.length+" · Muletillas detectadas: "+fillers);text("Recomendación: estructura tus ideas con introducción, argumentos y conclusión.");button("Continuar",()->practice());}}}
}